class Weight
  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    @unit == other.unit && @amount == other.amount
  end

  alias_method :eql?, :==

  def hash
    [@amount, @unit].hash
  end

  def <=>(other)
    raise ArgumentError, "Cannot compare weights with different units: #{@unit} vs #{other.unit}" unless @unit == other.unit
    @amount <=> other.amount
  end

  def <(other)
    raise ArgumentError, "Cannot compare weights with different units: #{@unit} vs #{other.unit}" unless @unit == other.unit
    @amount < other.amount
  end

  def <=(other)
    raise ArgumentError, "Cannot compare weights with different units: #{@unit} vs #{other.unit}" unless @unit == other.unit
    @amount <= other.amount
  end

  def >(other)
    raise ArgumentError, "Cannot compare weights with different units: #{@unit} vs #{other.unit}" unless @unit == other.unit
    @amount > other.amount
  end

  def >=(other)
    raise ArgumentError, "Cannot compare weights with different units: #{@unit} vs #{other.unit}" unless @unit == other.unit
    @amount >= other.amount
  end

  def clamp(min, max)
    [min, max].each do |bound|
      raise ArgumentError, "Cannot clamp weight with unit #{@unit} to a bound with unit #{bound.unit}" unless bound.is_a?(Weight) && bound.unit == @unit
    end

    result = @amount
    result = min.amount if result < min.amount
    result = max.amount if result > max.amount

    Weight.new(result, @unit)
  end

  def between?(min, max)
    raise ArgumentError, "Cannot use between? with weights of different units" unless @unit == min.unit && @unit == max.unit

    @amount >= min.amount && @amount <= max.amount
  end
end
