class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    if @packer
      @store[key] = { payload: @packer.dump(payload), stale: stale }
    else
      @store[key] = { payload: payload, stale: stale }
    end
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    # If the entry was removed by sweep, it won't exist in @store
    payload = entry[:payload]
    @packer ? @packer.load(payload) : payload
  end

  def sweep
    @store.keys.each do |key|
      entry = @store[key]
      if entry[:stale]
        @store.delete(key)
      end
    end
  end
end
