class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      define_getter(key)
      @attributes[key] = value
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    # Handle getter methods (e.g., name)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s.chomp('=').to_sym
      true
    else
      @attributes.key?(method_name) || method_name.to_s =~ /\A[a-zA-Z_][a-zA-Z0-9_]*=\z/
    end
  rescue NoMethodError
    false
  end

  def method_missing(method_name, *args, &block)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s.chomp('=').to_sym
      value = args.first
      define_getter(attr_name)
      @attributes[attr_name] = value
    else
      if @attributes.key?(method_name)
        @attributes[method_name]
      else
        super
      end
    end
  end

  private

  def define_getter(name)
    unless respond_to?(name, false)
      # Dynamically define a reader method for this attribute
      define_singleton_method(name) do
        @attributes[name]
      end
    end
  end
end
